// THE DISCRIMINATOR. Three receiver gaps have been attributed to "the
// receiver machinery"; this package exists to decide, by measurement rather
// than by argument, whether they are ONE mechanism or several.
//
// Every gap in this file is measured on TWO axes at once:
//
//   READ  -- `typeof o.m` / `typeof o[k]`. If the member does not resolve to
//            a function, the failure is MEMBER RESOLUTION and no amount of
//            receiver plumbing can fix it.
//   BIND  -- what the callee sees as `this`. If the member resolves and the
//            call runs but `this` is wrong, the failure is RECEIVER BINDING.
//
// and, for the binding half, with the AMBIENT-LEAK control that block/varint
// found decisive: make the same call from inside a METHOD whose receiver is a
// different object. A call primitive that simply forgets to bind leaves the
// window holding the ENCLOSING frame's `this`, so the callee reports the
// CALLER's receiver rather than `undefined`. That is a positive signature, not
// an absence, and it is what tells one dropped receiver from another.
"use strict";

function show(v) {
  if (v === undefined) return "undefined";
  if (v === null) return "null";
  if (typeof v !== "object") return typeof v + ":" + String(v);
  var tag;
  try { tag = v.tag; } catch (e) { tag = "(unreadable)"; }
  return "obj tag=" + (tag === undefined ? "(none)" : String(tag));
}
function t(f) { try { return String(f()); } catch (e) { return "THREW " + String(e && e.message); } }

// The probe method: reports what `this` was, from wherever it is installed.
function probe() { return show(this); }

// Keys held in module-scope `var`s, the way protobufjs holds its own.
var KM = "m", KUP = "trim", KTS = "toString", KHOP = "hasOwnProperty", KPUSH = "push";

// The ambient-leak driver. `new Outer().run()` is a constructed-object method
// call, which DOES bind, so while `run` is on the stack the ambient window
// holds OUTER. Anything `run` calls that forgets to bind will report OUTER.
function Outer(cb) { this.tag = "OUTER"; this.cb = cb; }
Outer.prototype.run = function () { return this.cb(); };
function fromMethod(cb) { return new Outer(cb).run(); }

// ---------------------------------------------------------------- M1
// RECORD tier: an object LITERAL with heterogeneous field types lowers to a
// typed record with a function-typed field. This is 4113.
function mkLit() { return { tag: "L", m: probe }; }
exports.m1ReadDot = function () { return t(function () { return typeof mkLit().m; }); };
exports.m1CallDot = function () { var o = mkLit(); return t(function () { return o.m(); }); };
exports.m1CallElem = function () { var o = mkLit(); return t(function () { return o[KM](); }); };
exports.m1CallDotFromMethod = function () {
  return t(function () { return fromMethod(function () { var o = mkLit(); return o.m(); }); });
};
// The control that says the record tier is the thing under test: the SAME
// member shape on a CONSTRUCTED object binds correctly on every side.
function Ctor() { this.tag = "C"; this.m = probe; }
exports.m1CtorControl = function () { return t(function () { return new Ctor().m(); }); };
// And the not-requested control: a record method that never reads `this` at
// all must be correct on every side, or the record tier is broken for a
// second reason and M1 pins two things.
exports.m1NoThisControl = function () {
  var o = { tag: "L", m: function () { return "no-this-ok"; } };
  return t(function () { return o.m(); });
};

// ---------------------------------------------------------------- M2
// DYN tier, OBJECT receiver. block/varint fixed the keyed CALL here. The
// question this row asks is whether the keyed READ was fixed with it.
function dobj() { var o = JSON.parse('{"a":1}'); o.tag = "D"; o.m = probe; return o; }
exports.m2ReadOwnElem = function () { var o = dobj(); return t(function () { return typeof o[KM]; }); };
exports.m2CallOwnElem = function () { var o = dobj(); return t(function () { return o[KM](); }); };
exports.m2ReadInhElem = function () { var o = dobj(); return t(function () { return typeof o[KHOP]; }); };
exports.m2CallInhElem = function () { var o = dobj(); return t(function () { return o[KHOP]("a"); }); };
exports.m2ReadInhDot = function () { var o = dobj(); return t(function () { return typeof o.hasOwnProperty; }); };
exports.m2CallInhDot = function () { var o = dobj(); return t(function () { return o.hasOwnProperty("a"); }); };

// ---------------------------------------------------------------- M3
// DYN tier, STRING receiver -- 4114's dUpper, the first residual gap.
function dstr() { return JSON.parse('"  ab  "'); }
exports.m3ReadElem = function () { var s = dstr(); return t(function () { return typeof s[KUP]; }); };
exports.m3ReadDot = function () { var s = dstr(); return t(function () { return typeof s.trim; }); };
exports.m3CallElem = function () { var s = dstr(); return t(function () { return "[" + s[KUP]() + "]"; }); };
exports.m3CallDot = function () { var s = dstr(); return t(function () { return "[" + s.trim() + "]"; }); };
exports.m3LenElem = function () { var s = dstr(); return t(function () { return s["length"]; }); };
exports.m3IdxElem = function () { var s = dstr(); return t(function () { return s[0]; }); };

// ---------------------------------------------------------------- M4
// DYN tier, NUMBER receiver -- 4114's dToString, the second residual gap.
function dnum() { return JSON.parse("5"); }
exports.m4ReadElem = function () { var n = dnum(); return t(function () { return typeof n[KTS]; }); };
exports.m4ReadDot = function () { var n = dnum(); return t(function () { return typeof n.toString; }); };
exports.m4CallElem = function () { var n = dnum(); return t(function () { return n[KTS](); }); };
exports.m4CallDot = function () { var n = dnum(); return t(function () { return n.toString(); }); };
exports.m4CallElemArg = function () { var n = dnum(); return t(function () { return n[KTS](2); }); };

// ---------------------------------------------------------------- M5
// DYN tier, ARRAY receiver -- the row block/varint already turned green, kept
// here as the in-package control that the keyed-invoke arm is live at all.
function darr() { return JSON.parse("[1,2,3]"); }
exports.m5ReadElem = function () { var a = darr(); return t(function () { return typeof a[KPUSH]; }); };
exports.m5CallElem = function () { var a = darr(); return t(function () { a[KPUSH](4); return a.join("-"); }); };

// M6 -- toString at a UNION/record receiver -- was measured from this same
// package and is NOT shipped here: that surface belongs to another block,
// and a pin on it from this file would turn their close into my red test.
// The measurement is in the block/recv report: on 5d8e2103 all four of its
// rows are COMPILE-TIME refusals (SC1090/SC2020/SC2001), which is a third
// mechanism again -- neither a dropped receiver nor a runtime resolution
// miss, but the static union/record member resolver declining before any
// code runs.
